package com.bank.bondsplit.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Interval DP: add both ends as boundaries, solve shorter spans first.
public class BondSplitService {
    private static final Logger log = Logger.getLogger(BondSplitService.class.getName());

    public int minSplitCost(int blockLength, int[] cuts) {
        int c = cuts.length;
        int[] pos = new int[c + 2];
        pos[0] = 0;                                        // left end of the block
        System.arraycopy(cuts, 0, pos, 1, c);
        pos[c + 1] = blockLength;                          // right end of the block
        Arrays.sort(pos);                                  // cuts become ordered boundaries
        int m = pos.length;
        int[][] dp = new int[m][m];                        // dp[i][j] = min cost of span (i,j)
        for (int len = 2; len < m; len++) {                // span width in boundary steps
            for (int i = 0; i + len < m; i++) {
                int j = i + len;
                int best = Integer.MAX_VALUE;
                for (int k = i + 1; k < j; k++) {           // first cut inside this span
                    int cost = (pos[j] - pos[i]) + dp[i][k] + dp[k][j];
                    best = Math.min(best, cost);
                }
                dp[i][j] = best;
            }
        }
        final int result = dp[0][m - 1];
        log.info(() -> "Minimum bond-split cost = " + result);
        return dp[0][m - 1];
    }
}
