package com.bank.bondsplit;

import com.bank.bondsplit.service.BondSplitService;
import java.util.logging.Logger;

public class BondSplitApplication {
    private static final Logger log = Logger.getLogger(BondSplitApplication.class.getName());

    public static void main(String[] args) {
        BondSplitService service = new BondSplitService();
        int[] cuts = {1, 3, 4};                            // required denomination boundaries
        int cost = service.minSplitCost(7, cuts);          // block of face value 7
        log.info(() -> "Final minimum split cost = " + cost);
    }
}
